1	import {jest} from '@jest/globals';
2	import {createConnectionHandler, type ConnectionHandlerDeps, type ExtWebSocket} from './connectionHandler.js';
3	import type {ChatSession} from '../../types/session.js';
4	import type {SessionStore} from '../../types/sessionStore.js';
5	import {captureErrors} from '../../shared/logCaptureTestSupport.js';
6	
7	// Pins the lifecycle hooks: that onConnect is called at all, when, and that neither hook can kill a connection.
8	
9	// Drains the microtask queue the hook is deferred onto.
10	const settle = () => new Promise<void>(resolve => setTimeout(resolve, 0));
11	
12	type HarnessOptions = Partial<
13	  Pick<ConnectionHandlerDeps, 'onConnect' | 'onDisconnect' | 'sessionStore' | 'handleMessage'>
14	>;
15	
16	const harness = (options: HarnessOptions = {}) => {
17	  const sent: string[] = [];
18	  const listeners = new Map<string, (arg?: unknown) => void>();
19	
20	  const ws = {
21	    userId: 'u1',
22	    isAlive: true,
23	    send: (raw: string) => sent.push(raw),
24	    on: (event: string, fn: (arg?: unknown) => void) => listeners.set(event, fn),
25	    // The handler pauses the socket across an awaited create and resumes once its listeners are attached.
26	    pause: () => undefined,
27	    resume: () => undefined,
28	    close: () => undefined,
29	  } as unknown as ExtWebSocket;
30	
31	  const deleted: string[] = [];
32	  const sessionStore = {
33	    create: (sessionId: string, userId: string | number): ChatSession => ({sessionId, userId, entries: []}),
34	    delete: (sessionId: string) => (deleted.push(sessionId), true),
35	  } as unknown as SessionStore;
36	
37	  const deps = {
38	    wsAuth: jest.fn(),
39	    sessionStore,
40	    handleMessage: jest.fn(),
41	    basePath: '/hal',
42	    ...options,
43	  } as unknown as ConnectionHandlerDeps;
44	
45	  const connect = () => createConnectionHandler(deps, [])(ws);
46	
47	  return {
48	    connect,
49	    sent,
50	    deleted,
51	    handleMessage: deps.handleMessage as jest.Mock,
52	    close: () => listeners.get('close')?.(),
53	    receive: (frame: string) => listeners.get('message')?.(frame),
54	  };
55	};
56	
57	describe('the websocket connection handler', () => {
58	  describe('onConnect', () => {
59	    it('is called once for an accepted connection, with the session the socket was given', async () => {
60	      const seen: ChatSession[] = [];
61	      const {connect, sent} = harness({onConnect: session => void seen.push(session)});
62	
63	      connect();
64	      await settle();
65	
66	      const frame = JSON.parse(sent[0]) as {type: string; sessionId: string};
67	      expect({calls: seen.length, sessionId: seen[0]?.sessionId}).toEqual({calls: 1, sessionId: frame.sessionId});
68	    });
69	
70	    // A REST chat id is not a socket session id: the socket mints its own, so neither can be guessed
71	    it('mints a fresh session id per connection rather than reusing one', async () => {
72	      const first = harness();
73	      const second = harness();
74	
75	      first.connect();
76	      second.connect();
77	      await settle();
78	
79	      const id = (raw: string) => (JSON.parse(raw) as {sessionId: string}).sessionId;
80	      expect(id(first.sent[0]) === id(second.sent[0])).toBe(false);
81	    });
82	
83	    // Counted inside the hook: the connected frame is sent after an awaited create, so no synchronous read sees it.
84	    it('runs after the connected frame is sent, not before it', async () => {
85	      const framesAtHook: number[] = [];
86	      let frames: string[] = [];
87	      const {connect, sent} = harness({onConnect: () => void framesAtHook.push(frames.length)});
88	      frames = sent;
89	
90	      connect();
91	      await settle();
92	
93	      expect(framesAtHook).toEqual([1]);
94	    });
95	
96	    it('is deferred, so it never runs inside the connection listener', () => {
97	      const order: string[] = [];
98	      const {connect} = harness({onConnect: () => void order.push('hook')});
99	
100	      connect();
101	
102	      expect(order).toEqual([]);
103	    });
104	
105	    it('survives a hook that throws synchronously', async () => {
106	      const {connect} = harness({
107	        onConnect: () => {
108	          throw new Error('hook exploded');
109	        },
110	      });
111	
112	      connect();
113	
114	      await expect(settle()).resolves.toBeUndefined();
115	    });
116	
117	    it('survives a hook that rejects', async () => {
118	      const {connect} = harness({onConnect: () => Promise.reject(new Error('hook rejected'))});
119	
120	      connect();
121	
122	      await expect(settle()).resolves.toBeUndefined();
123	    });
124	
125	    it('is optional, so a connection without one still sends its frame', async () => {
126	      const {connect, sent} = harness();
127	
128	      connect();
129	      await settle();
130	
131	      expect(sent.length).toBe(1);
132	    });
133	  });
134	
135	  describe('onDisconnect', () => {
136	    // The close path erases nothing now, so the hook is the only thing a consumer can hang cleanup on.
137	    it('is called with the session id while the store still holds the session', async () => {
138	      const seen: string[] = [];
139	      const {connect, sent, close, deleted} = harness({onDisconnect: id => void seen.push(id)});
140	
141	      connect();
142	      await settle();
143	      const {sessionId} = JSON.parse(sent[0]) as {sessionId: string};
144	      close();
145	      await settle();
146	
147	      expect({seen, deleted}).toEqual({seen: [sessionId], deleted: []});
148	    });
149	
150	    it('does not let a throwing hook escape the close listener', () => {
151	      const {connect, close} = harness({
152	        onDisconnect: () => {
153	          throw new Error('hook exploded');
154	        },
155	      });
156	      connect();
157	
158	      expect(() => close()).not.toThrow();
159	    });
160	
161	    it('does not let a rejecting hook reach the process', async () => {
162	      const {connect, close} = harness({onDisconnect: () => Promise.reject(new Error('hook rejected'))});
163	      connect();
164	
165	      close();
166	
167	      await expect(settle()).resolves.toBeUndefined();
168	    });
169	  });
170	
171	  describe('the connection signal', () => {
172	    it('hands every message on a connection the same signal, and each connection its own', async () => {
173	      const first = harness();
174	      const second = harness();
175	      first.connect();
176	      second.connect();
177	      await settle();
178	
179	      first.receive(JSON.stringify({type: 'ping', timestamp: 1}));
180	      first.receive(JSON.stringify({type: 'ping', timestamp: 2}));
181	      second.receive(JSON.stringify({type: 'ping', timestamp: 3}));
182	      // Off-lock frames dispatch on the answer chain, one microtask later than the frame itself.
183	      await settle();
184	
185	      const {calls: firstCalls} = first.handleMessage.mock;
186	      const {calls: secondCalls} = second.handleMessage.mock;
187	      const [one, two, other] = [...firstCalls, ...secondCalls].map(call => call[3]);
188	      expect({isSignal: one instanceof AbortSignal, shared: one === two, own: one !== other}).toEqual({
189	        isSignal: true,
190	        shared: true,
191	        own: true,
192	      });
193	    });
194	
195	    it('aborts the connection signal when its socket closes, before onDisconnect is called', async () => {
196	      const abortedAtDisconnect: unknown[] = [];
197	      const handed: {signal?: AbortSignal} = {};
198	      const {connect, receive, close, handleMessage} = harness({
199	        onDisconnect: () => void abortedAtDisconnect.push(handed.signal?.aborted),
200	      });
201	      connect();
202	      await settle();
203	      receive(JSON.stringify({type: 'ping', timestamp: 1}));
204	      await settle();
205	      const {calls} = handleMessage.mock;
206	      handed.signal = calls[0]?.[3] as AbortSignal | undefined;
207	      const beforeClose = handed.signal?.aborted;
208	
209	      close();
210	
211	      expect({beforeClose, abortedAtDisconnect}).toEqual({beforeClose: false, abortedAtDisconnect: [true]});
212	    });
213	  });
214	
215	  describe('inbound frames', () => {
216	    it('answers unparseable JSON with INVALID_FORMAT alone and never dispatches it', async () => {
217	      const {connect, sent, receive, handleMessage} = harness();
218	      connect();
219	      // The message listener is attached once the awaited create resolves.
220	      await settle();
221	
222	      receive('{"type": "user_message", "content": ');
223	
224	      const types = sent.slice(1).map(raw => (JSON.parse(raw) as {type: string; code?: string}).code ?? 'no code');
225	      const {calls} = handleMessage.mock;
226	      expect({afterConnected: types, dispatched: calls.length}).toEqual({
227	        afterConnected: ['INVALID_FORMAT'],
228	        dispatched: 0,
229	      });
230	    });
231	
232	    // A frame whose answer is pending must hold the frame behind it: a client pipelining a list and a
233	    // ping reads session_list before pong, in the order it sent them.
234	    it('dispatches frames that bypass the session lock one answer at a time, in the order they arrived', async () => {
235	      let releaseList!: () => void;
236	      const held = new Promise<void>(resolve => {
237	        releaseList = resolve;
238	      });
239	      const {connect, receive, handleMessage} = harness({
240	        handleMessage: jest
241	          .fn()
242	          .mockImplementation((_ws: unknown, _session: unknown, frame: unknown) =>
243	            (frame as {type: string}).type === 'user_message' ? Promise.resolve() : held
244	          ),
245	      });
246	      connect();
247	      await settle();
248	
249	      receive(JSON.stringify({type: 'list_sessions'}));
250	      await settle();
251	      receive(JSON.stringify({type: 'ping', timestamp: 1}));
252	
253	      expect(handleMessage).toHaveBeenCalledTimes(1);
254	      releaseList();
255	      await settle();
256	      expect(handleMessage.mock.calls[1]?.[2]).toEqual({type: 'ping', timestamp: 1});
257	    });
258	
259	    it('still dispatches a turn at once while a list answer ahead of it is pending', async () => {
260	      let releaseList!: () => void;
261	      const held = new Promise<void>(resolve => {
262	        releaseList = resolve;
263	      });
264	      const {connect, receive, handleMessage} = harness({
265	        handleMessage: jest
266	          .fn()
267	          .mockImplementation((_ws: unknown, _session: unknown, frame: unknown) =>
268	            (frame as {type: string}).type === 'user_message' ? Promise.resolve() : held
269	          ),
270	      });
271	      connect();
272	      await settle();
273	
274	      receive(JSON.stringify({type: 'list_sessions'}));
275	      await settle();
276	      receive(JSON.stringify({type: 'user_message', content: 'hello'}));
277	
278	      expect(handleMessage).toHaveBeenCalledTimes(2);
279	      expect(handleMessage.mock.calls[1]?.[2]).toEqual({type: 'user_message', content: 'hello'});
280	      releaseList();
281	    });
282	  });
283	});
284	
285	// A durable erase that fails silently would be recorded as done, so the close path has to report it.
286	describe('a session store that fails to release', () => {
287	  const errors = captureErrors();
288	
289	  it('logs a rejecting evict rather than dropping it', async () => {
290	    const evicted: string[] = [];
291	    const sessionStore = {
292	      create: async (sessionId: string, userId: string | number): Promise<ChatSession> => {
293	        await settle();
294	        return {sessionId, userId, entries: []};
295	      },
296	      evict: (sessionId: string) => {
297	        evicted.push(sessionId);
298	        return Promise.reject(new Error('store unreachable'));
299	      },
300	    } as unknown as SessionStore;
301	    const {connect, close} = harness({sessionStore});
302	
303	    connect();
304	    close();
305	    await settle();
306	    await settle();
307	
308	    expect(errors).toEqual([
309	      {category: 'ws', message: 'session evict failed', sessionId: evicted[0], error: 'store unreachable'},
310	    ]);
311	  });
312	
313	  it('stays silent for a connection that was never handed a session', async () => {
314	    const seen: string[] = [];
315	    const sessionStore = {
316	      create: () => Promise.reject(new Error('store down')),
317	      delete: () => true,
318	    } as unknown as SessionStore;
319	    const {connect, close} = harness({sessionStore, onDisconnect: id => void seen.push(id)});
320	
321	    connect();
322	    await settle();
323	    close();
324	    await settle();
325	
326	    expect(seen).toEqual([]);
327	  });
328	
329	  it('clears the credentials of a session whose socket closed before it was delivered', async () => {
330	    const created: ChatSession[] = [];
331	    const sessionStore = {
332	      create: async (sessionId: string, userId: string | number): Promise<ChatSession> => {
333	        await settle();
334	        const session: ChatSession = {sessionId, userId, entries: [], authHeaders: {authorization: 'Bearer t'}};
335	        created.push(session);
