344	    await settle();
345	
346	    expect(created.map(session => session.authHeaders)).toEqual([undefined]);
347	  });
348	
349	  // One socket whose send throws, driven twice: once for what the socket sees, once for what the store keeps.
350	  const setupThatFails = (sessionStore: SessionStore) => {
351	    const calls: string[] = [];
352	    const listeners = new Map<string, (arg?: unknown) => void>();
353	    const ws = {
354	      userId: 'u1',
355	      isAlive: true,
356	      send: () => {
357	        throw new Error('socket gone');
358	      },
359	      on: (event: string, fn: (arg?: unknown) => void) => listeners.set(event, fn),
360	      pause: () => void calls.push('pause'),
361	      resume: () => void calls.push('resume'),
362	      close: () => void calls.push('close'),
363	    } as unknown as ExtWebSocket;
364	    const deps = {
365	      wsAuth: jest.fn(),
366	      sessionStore,
367	      handleMessage: jest.fn(),
368	      basePath: '/hal',
369	    } as unknown as ConnectionHandlerDeps;
370	
371	    createConnectionHandler(deps, [])(ws);
372	    return calls;
373	  };
374	
375	  const holdingStore = (evicted: string[]) =>
376	    ({
377	      create: (sessionId: string, userId: string | number): ChatSession => ({sessionId, userId, entries: []}),
378	      evict: (sessionId: string) => (evicted.push(sessionId), true),
379	    }) as unknown as SessionStore;
