382	    const calls = setupThatFails(holdingStore([]));
383	
384	    await settle();
385	
386	    expect(calls).toEqual(['pause', 'resume', 'close']);
387	  });
388	
389	  it('evicts a session it created but could not hand over', async () => {
390	    const evicted: string[] = [];
391	
392	    setupThatFails(holdingStore(evicted));
393	    await settle();
394	
395	    expect(evicted).toHaveLength(1);
396	  });
