104	    });
105	  };
106	}
107	
108	// The sockets open on each session, oldest first: a resumed session can be open on more than one at once.
109	const openSockets = new WeakMap<ChatSession, ExtWebSocket[]>();
110	
111	async function openSession(deps: ConnectionHandlerDeps, examplePrompts: string[], ws: ExtWebSocket): Promise<void> {
112	  // A requested id is never adopted for a new session: that would be session fixation.
113	  let sessionId = uuidv4();
114	  const state = {closed: false, settled: false, notified: false, delivered: false};
115	  const held: {session?: ChatSession; socket: ExtWebSocket} = {socket: ws};
116	  // One per connection, not per message or session: a close abandons the turn in flight and every message queued behind it.
117	  const connection = new AbortController();
118	
119	  ws.on('error', (error: Error) => {
120	    log.error('ws', 'connection error', {sessionId, error: error.message});
121	  });
122	
123	  ws.on('pong', () => {
124	    ws.isAlive = true;
125	  });
126	
127	  ws.on('close', () => {
128	    // First, so the turn stops before the session is torn down and before onDisconnect.
129	    connection.abort();
130	    state.closed = true;
131	    log.info('ws', 'disconnected', {sessionId});
132	    if (state.settled) endSession(deps, sessionId, state, held);
133	  });
134	
135	  // Paused across the await so a frame arriving before the message listener exists is buffered, not dropped.
136	  ws.pause();
137	
138	  const outcome = await resumableSession(deps.sessionStore, ws, deps.resume);
139	  const resumed = outcome.session;
140	  if (resumed) sessionId = resumed.sessionId;
141	  const session = resumed ?? (await createSession(deps, sessionId, ws));
142	  state.settled = true;
143	
144	  if (session === undefined) {
145	    // Resumed before closing: ws.close() on a paused socket waits for a close frame it can never read.
146	    ws.resume();
147	    ws.close(1011, 'Session store unavailable');
148	    return;
149	  }
150	
151	  // A new session is this socket's from the start; a resumed one only once this socket is known to be open.
152	  if (!resumed) join(session, ws);
153	
154	  if (state.closed) {
155	    // Held first: a store that implements no evict still holds this session, and it carries the caller's credentials.
156	    held.session = session;
157	    await evictUnlessResumed(deps, sessionId, resumed);
158	    endSession(deps, sessionId, state, held);
159	    ws.resume();
160	    return;
161	  }
162	
163	  if (resumed) join(resumed, ws);
164	  held.session = session;
165	
166	  log.info('ws', 'connected', {sessionId, userId: ws.userId});
167	
168	  const connected: ConnectedMessage = {
169	    type: 'connected',
170	    sessionId,
171	    message: 'Connected to HAL Engine',
172	    examplePrompts,
173	    ...resumeFields(deps.resume, outcome),
174	  };
175	  // A socket that died between the check above and this frame must not leave the session it was created for behind.
176	  try {
177	    ws.send(JSON.stringify(connected));
178	    if (resumed) replayEntries(ws, resumed);
179	  } catch (error) {
180	    log.error('ws', 'connected frame failed', {sessionId, error: messageOf(error)});
181	    await evictUnlessResumed(deps, sessionId, resumed);
182	    endSession(deps, sessionId, state, held);
183	    ws.resume();
184	    ws.close(1011, 'Connection setup failed');
185	    return;
186	  }
187	
188	  state.delivered = true;
189	
190	  // Deferred, not inline: a synchronous throw in the `connection` listener corrupts an already-upgraded socket.
191	
192	  // A microtask, not setImmediate: it drains before the loop delivers any inbound frame on this socket.
193	  queueMicrotask(() =>
194	    runHook('onConnect', sessionId, () => deps.onConnect?.(session, {resumed: resumed !== undefined}))
195	  );
196	
197	  // Off-lock frames still dispatch one answer at a time, in arrival order, so a pipelined ping reads session_list first; a turn does not join this chain — the lock orders turns, and a ping must not wait behind one.
198	  let dispatched: Promise<void> = Promise.resolve();
199	  ws.on('message', (frame: Buffer | string) => {
200	    const parsed = parseWsData(frame);
201	    if (parsed === null) {
202	      sendError(ws, ErrorCodes.INVALID_FORMAT, 'Invalid JSON');
203	      return;
204	    }
205	    log.info('ws', 'message received', {sessionId, type: (parsed as Record<string, unknown>).type as string});
206	    if (isUserMessageFrame(parsed)) {
207	      deps.handleMessage(ws, session, parsed, connection.signal);
208	      return;
209	    }
210	    dispatched = dispatched
211	      // One answer failing must not skip the frames queued behind it.
212	      .catch(() => undefined)
213	      .then(() => deps.handleMessage(ws, session, parsed, connection.signal))
214	      .catch(() => undefined);
215	  });
216	
217	  ws.resume();
218	}
