220	// Joined as the newest socket on the session, which carries this upgrade's credentials from here on.
221	function join(session: ChatSession, ws: ExtWebSocket): void {
222	  openSockets.set(session, [...(openSockets.get(session) ?? []), ws]);
223	  session.authHeaders = ws.authHeaders;
224	}
