226	// `undefined` rather than a throw: one store failure closes one socket instead of ending the process.
227	async function createSession(
228	  deps: ConnectionHandlerDeps,
229	  sessionId: string,
230	  ws: ExtWebSocket
231	): Promise<ChatSession | undefined> {
232	  try {
233	    return await deps.sessionStore.create(sessionId, ws.userId, {
234	      authHeaders: ws.authHeaders,
235	      workspaceId: ws.workspaceId,
236	    });
237	  } catch (error) {
238	    log.error('ws', 'session create failed', {userId: ws.userId, error: messageOf(error)});
239	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Could not start a session');
240	    return undefined;
241	  }
242	}
243	
244	// The close path erases nothing: the conversation outlives its socket, and `onDisconnect` is the consumer's seam.
245	function endSession(
246	  deps: ConnectionHandlerDeps,
247	  sessionId: string,
248	  state: {notified: boolean; delivered: boolean},
249	  held: {session?: ChatSession; socket: ExtWebSocket}
250	): void {
251	  if (state.notified) return;
252	  state.notified = true;
253	
254	  if (held.session) leave(held.session, held.socket);
255	
256	  // Only for a session the consumer was actually handed: onDisconnect is the other half of onConnect, not of a socket.
257	  if (!state.delivered) return;
258	
259	  runHook('onDisconnect', sessionId, () => deps.onDisconnect?.(sessionId));
260	}
261	
262	// The newest socket still open lends the session its credentials; with none left, nothing keeps them or a closed socket.
263	function leave(session: ChatSession, ws: ExtWebSocket): void {
264	  const open = openSockets.get(session) ?? [];
265	  if (!open.includes(ws)) return;
266	  const remaining = open.filter(socket => socket !== ws);
267	  const newest = remaining.at(-1);
268	  if (newest === undefined) {
269	    openSockets.delete(session);
270	    session.authHeaders = undefined;
271	    return;
272	  }
273	  openSockets.set(session, remaining);
274	  session.authHeaders = newest.authHeaders;
275	}
276	
277	// Never a resumed session: evict erases, and a resumed session holds the conversation being rejoined.
278	async function evictUnlessResumed(
279	  deps: ConnectionHandlerDeps,
280	  sessionId: string,
281	  resumed: ChatSession | undefined
282	): Promise<void> {
283	  if (!resumed) await evictSession(deps, sessionId);
284	}
285	
286	// Only for a session no client ever received: it has no entries and nothing to migrate.
287	async function evictSession(deps: ConnectionHandlerDeps, sessionId: string): Promise<void> {
288	  try {
289	    await deps.sessionStore.evict?.(sessionId);
290	  } catch (error) {
291	    log.error('ws', 'session evict failed', {sessionId, error: messageOf(error)});
292	  }
293	}
294	
295	// Consumer hooks are fire-and-forget: the engine never awaits one and never lets one take the connection down.
296	function runHook(name: string, sessionId: string, call: () => void | Promise<void>): void {
297	  try {
298	    // Promise.resolve also absorbs a thenable from another realm, where `instanceof Promise` is false.
299	    void Promise.resolve(call()).catch((error: unknown) => logHookFailure(name, sessionId, error));
300	  } catch (error) {
301	    logHookFailure(name, sessionId, error);
302	  }
303	}
304	
305	function logHookFailure(name: string, sessionId: string, error: unknown): void {
306	  log.error('ws', `${name} hook failed`, {sessionId, error: messageOf(error)});
307	}
308	
309	function messageOf(error: unknown): string {
310	  if (typeof error === 'object' && error !== null && 'message' in error) return String(error.message);
311	  return String(error);
312	}
